export interface ConnectorConfig {
  /** Airtable Personal Access Token for Airtable API */
  airtableToken: string
  /** Airtable Base ID */
  airtableBaseId: string
  /** Airtable Webhook ID */
  airtableWebhookId: string
  /** Discord webhook URL (format: https://discord.com/api/webhooks/{id}/{token}) */
  discordWebhookUrl: string
  /** Optional fetch implementation for testing */
  fetch?: typeof fetch
}

export interface AirtablePayload {
  id: string
  baseTransactionNumber: number
  timestamp: string
  data: {
    records: AirtableRecord[]
  }
}

export interface AirtableRecord {
  id: string
  fields: {
    Name?: string
    Email?: string
    CreatedTime?: string
    [key: string]: unknown
  }
}

export interface AirtableWebhookPayload {
  payloads: AirtablePayload[]
}

export interface DiscordWebhookResponse {
  id: string
  channel_id: string
  content: string
  timestamp: string
}

export interface HandleResult {
  sent: Array<{
    recordId: string
    discordMessageId: string
  }>
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validateConfig(config: ConnectorConfig): void {
  if (!config.airtableToken) throw new Error('Missing required config: airtableToken')
  if (!config.airtableBaseId) throw new Error('Missing required config: airtableBaseId')
  if (!config.airtableWebhookId) throw new Error('Missing required config: airtableWebhookId')
  if (!config.discordWebhookUrl) throw new Error('Missing required config: discordWebhookUrl')
}

function validatePayload(payload: unknown): asserts payload is AirtableWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected object')
  }
  const p = payload as Record<string, unknown>
  if (!Array.isArray(p.payloads)) {
    throw new Error('Invalid payload: missing "payloads" array')
  }
  for (const item of p.payloads) {
    if (!item || typeof item !== 'object') throw new Error('Invalid payload item: expected object')
    const itemObj = item as Record<string, unknown>
    if (!itemObj.data || typeof itemObj.data !== 'object') {
      throw new Error('Invalid payload item: missing "data" object')
    }
    const data = itemObj.data as Record<string, unknown>
    if (!Array.isArray(data.records)) {
      throw new Error('Invalid payload item: missing "data.records" array')
    }
  }
}

function formatRecordContent(record: AirtableRecord): string {
  const parts = [`New record: ${record.id}`]
  const fields = record.fields
  if (fields.Name) parts.push(`Name: ${fields.Name}`)
  if (fields.Email) parts.push(`Email: ${fields.Email}`)
  if (fields.CreatedTime) parts.push(`CreatedTime: ${fields.CreatedTime}`)
  return parts.join(' - ')
}

async function sendToDiscord(
  webhookUrl: string,
  content: string,
  fetchFn: typeof fetch
): Promise<DiscordWebhookResponse> {
  const response = await fetchFn(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  })

  if (!response.ok) {
    throw new Error(`Discord webhook failed: ${response.status} ${response.statusText} at ${webhookUrl}`)
  }

  return (await response.json()) as DiscordWebhookResponse
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validateConfig(config)
  validatePayload(payload)

  const fetchFn = getFetch(config)
  const airtablePayload = payload as AirtableWebhookPayload
  const sent: HandleResult['sent'] = []

  for (const payloadItem of airtablePayload.payloads) {
    for (const record of payloadItem.data.records) {
      const content = formatRecordContent(record)
      const discordResponse = await sendToDiscord(config.discordWebhookUrl, content, fetchFn)
      sent.push({
        recordId: record.id,
        discordMessageId: discordResponse.id,
      })
    }
  }

  return { sent }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, AirtableWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      airtableToken: 'pat_test_token',
      airtableBaseId: 'appTestBase',
      airtableWebhookId: 'whTestWebhook',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.sent.length).toBe(1)
    expect(result.sent[0].recordId).toBe('recAbCdEfGhIjKlMnO')
    expect(result.sent[0].discordMessageId).toBe('1087654321098765432')
  })
})

describe('handle', () => {
  it('sends formatted message to Discord for each record', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://discord.com/api/webhooks/123456/abcdef' && req.method === 'POST') {
        return jsonResponse({
          id: 'msg_123',
          channel_id: 'chan_456',
          content: req.json?.content,
          timestamp: '2023-04-10T12:34:56.789Z',
        })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      airtableToken: 'pat_test',
      airtableBaseId: 'base_1',
      airtableWebhookId: 'wh_1',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch,
    }

    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'rec1',
          baseTransactionNumber: 1,
          timestamp: '2023-04-10T12:34:56.000Z',
          data: {
            records: [
              {
                id: 'rec1',
                fields: {
                  Name: 'Alice',
                  Email: 'alice@example.com',
                  CreatedTime: '2023-04-10T12:34:56.000Z',
                },
              },
              {
                id: 'rec2',
                fields: {
                  Name: 'Bob',
                  Email: 'bob@example.com',
                },
              },
            ],
          },
        },
      ],
    }

    const result = await handle(payload, config)

    expect(result.sent).toHaveLength(2)
    expect(result.sent[0].recordId).toBe('rec1')
    expect(result.sent[1].recordId).toBe('rec2')
    expect(calls).toHaveLength(2)
    expect(calls[0].json).toEqual({
      content: 'New record: rec1 - Name: Alice, Email: alice@example.com, CreatedTime: 2023-04-10T12:34:56.000Z',
    })
    expect(calls[1].json).toEqual({
      content: 'New record: rec2 - Name: Bob, Email: bob@example.com',
    })
  })

  it('uses Bearer auth for Airtable config validation', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ id: 'msg_1' }, 200))

    const config: ConnectorConfig = {
      airtableToken: 'pat_secret_token',
      airtableBaseId: 'base_1',
      airtableWebhookId: 'wh_1',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch,
    }

    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'rec1',
          baseTransactionNumber: 1,
          timestamp: '2023-04-10T12:34:56.000Z',
          data: { records: [{ id: 'rec1', fields: { Name: 'Test' } }] },
        },
      ],
    }

    await handle(payload, config)
    // Config validation passes, no Airtable API call is made in this connector
    // (the payload is already provided). The token is validated as present.
    expect(calls.length).toBe(1)
  })

  it('throws on missing required config fields', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: AirtableWebhookPayload = {
      payloads: [{ id: 'rec1', baseTransactionNumber: 1, timestamp: '2023-04-10T12:34:56.000Z', data: { records: [] } }],
    }

    await expect(handle(payload, { ...{ airtableToken: '', airtableBaseId: '', airtableWebhookId: '', discordWebhookUrl: '' }, fetch })).rejects.toThrow('Missing required config: airtableToken')
    await expect(handle(payload, { airtableToken: 't', airtableBaseId: '', airtableWebhookId: '', discordWebhookUrl: '', fetch })).rejects.toThrow('Missing required config: airtableBaseId')
    await expect(handle(payload, { airtableToken: 't', airtableBaseId: 'b', airtableWebhookId: '', discordWebhookUrl: '', fetch })).rejects.toThrow('Missing required config: airtableWebhookId')
    await expect(handle(payload, { airtableToken: 't', airtableBaseId: 'b', airtableWebhookId: 'w', discordWebhookUrl: '', fetch })).rejects.toThrow('Missing required config: discordWebhookUrl')
  })

  it('throws on invalid payload structure', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtableToken: 't',
      airtableBaseId: 'b',
      airtableWebhookId: 'w',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }

    await expect(handle(null, config)).rejects.toThrow('Invalid payload: expected object')
    await expect(handle({ payloads: 'not-array' }, config)).rejects.toThrow('Invalid payload: missing "payloads" array')
    await expect(handle({ payloads: [{}] }, config)).rejects.toThrow('Invalid payload item: missing "data" object')
    await expect(handle({ payloads: [{ data: {} }] }, config)).rejects.toThrow('Invalid payload item: missing "data.records" array')
  })

  it('throws on non-2xx Discord response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ message: 'Unauthorized' }, 401))

    const config: ConnectorConfig = {
      airtableToken: 't',
      airtableBaseId: 'b',
      airtableWebhookId: 'w',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch,
    }

    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'rec1',
          baseTransactionNumber: 1,
          timestamp: '2023-04-10T12:34:56.000Z',
          data: { records: [{ id: 'rec1', fields: { Name: 'Test' } }] },
        },
      ],
    }

    await expect(handle(payload, config)).rejects.toThrow('Discord webhook failed: 401 Unauthorized at https://discord.com/api/webhooks/123456/abcdef')
    expect(calls).toHaveLength(1)
  })

  it('handles records with missing optional fields', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) =>
      jsonResponse({ id: 'msg_1', channel_id: 'c1', content: req.json?.content, timestamp: '2023-04-10T12:34:56.789Z' })
    )

    const config: ConnectorConfig = {
      airtableToken: 't',
      airtableBaseId: 'b',
      airtableWebhookId: 'w',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch,
    }

    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'rec_minimal',
          baseTransactionNumber: 1,
          timestamp: '2023-04-10T12:34:56.000Z',
          data: { records: [{ id: 'rec_minimal', fields: {} }] },
        },
      ],
    }

    const result = await handle(payload, config)
    expect(result.sent[0].recordId).toBe('rec_minimal')
    expect(calls[0].json).toEqual({ content: 'New record: rec_minimal' })
  })
})

