export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validateConfig(config)
  validatePayload(payload)

  const fetchFn = getFetch(config)
  const airtablePayload = payload as AirtableWebhookPayload
  const sent: HandleResult['sent'] = []

  for (const payloadItem of airtablePayload.payloads) {
    for (const record of payloadItem.data.records) {
      const content = formatRecordContent(record)
      const discordResponse = await sendToDiscord(config.discordWebhookUrl, content, fetchFn)
      sent.push({
        recordId: record.id,
        discordMessageId: discordResponse.id,
      })
    }
  }

  return { sent }
}

